import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import * as issueService from "@/server/services/issue-service";
import * as labelService from "@/server/services/label-service";
import * as labelRepo from "@/server/repositories/label-repository";
import { mergeLabelsSchema } from "@/schemas/label";
import { NotFoundError } from "@/server/services/_support";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("merges", async () => {
  const t = await createTenant("mergeorg");
  const o = await createTenant("otherorg");
  const admin = t.actors.admin;
  const bug = await labelService.createLabel(admin, { orgId: t.org.id, name: "bug", color: "#ff0000", description: null });
  const defect = await labelService.createLabel(admin, { orgId: t.org.id, name: "defect", color: "#ff0000", description: null });
  const other = await labelService.createLabel(admin, { orgId: t.org.id, name: "other", color: "#ff0000", description: null });
  const foreign = await labelService.createLabel(o.actors.admin, { orgId: o.org.id, name: "defect", color: "#ff0000", description: null });
  const i1 = await issueService.createIssue(admin, issueInput(t.org.id, t.project.id, { title: "a" }));
  const i2 = await issueService.createIssue(admin, issueInput(t.org.id, t.project.id, { title: "b" }));
  const i3 = await issueService.createIssue(admin, issueInput(t.org.id, t.project.id, { title: "c" }));
  const i4 = await issueService.createIssue(admin, issueInput(t.org.id, t.project.id, { title: "d" }));
  await labelRepo.setIssueLabels(t.org.id, i1.id, [defect.id]);
  await labelRepo.setIssueLabels(t.org.id, i2.id, [defect.id, bug.id, other.id]);
  await labelRepo.setIssueLabels(t.org.id, i3.id, [other.id]);
  await labelRepo.setIssueLabels(t.org.id, i4.id, [defect.id]);
  await issueService.archiveIssue(admin, t.org.id, i4.id).catch((e) => console.log("archive", e.message));

  expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: bug.id, targetLabelId: bug.id }).success).toBe(false);
  expect(mergeLabelsSchema.safeParse({ orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id }).success).toBe(true);
  await expect(labelService.mergeLabels(t.actors.member, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id })).rejects.toBeInstanceOf(PermissionDeniedError);
  await expect(labelService.mergeLabels(admin, { orgId: o.org.id, sourceLabelId: defect.id, targetLabelId: bug.id })).rejects.toBeInstanceOf(TenantScopeError);
  await expect(labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: foreign.id, targetLabelId: bug.id })).rejects.toBeInstanceOf(NotFoundError);
  await expect(labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: foreign.id })).rejects.toBeInstanceOf(NotFoundError);
  await expect(labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: bug.id, targetLabelId: bug.id })).rejects.toThrow();

  const res = await labelService.mergeLabels(admin, { orgId: t.org.id, sourceLabelId: defect.id, targetLabelId: bug.id });
  expect(res.issuesRelabelled).toBe(3);
  expect(res.label).toEqual(bug);
  const map = await labelRepo.listLabelsForIssues(t.org.id, [i1.id, i2.id, i3.id, i4.id]);
  const names = (id: string) => (map[id] ?? []).map((l) => l.name).sort();
  expect(names(i1.id)).toEqual(["bug"]);
  expect(names(i2.id)).toEqual(["bug", "other"]);
  expect(names(i3.id)).toEqual(["other"]);
  expect(names(i4.id)).toEqual(["bug"]);
  expect((await labelRepo.listLabels(t.org.id)).map((l) => l.name)).toEqual(["bug", "other"]);
  expect((await labelRepo.listLabels(o.org.id)).map((l) => l.name)).toEqual(["defect"]);
});
EOF
